import React, { useState, useEffect } from 'react';
import api from '../api';

function RentalForm({ car, onSubmit, onCancel }) {

    const [customers, setCustomers] = useState([]);
    const [customerId, setCustomerId] = useState('');
    const [customerName, setCustomerName] = useState('');
    const [customerPhone, setCustomerPhone] = useState('');
    const [pickupDate, setPickupDate] = useState('');
    const [returnDate, setReturnDate] = useState('');

    useEffect(function() {

        api.findAllCustomers().then(function(response) {
            setCustomers(response.data);
        }).catch(function() {});

    }, []);

    function handleCustomerChange(e) {

        var selectedId = e.target.value;
        setCustomerId(selectedId);

        if (selectedId) {
            var customer = customers.find(function(c) { return c.id === parseInt(selectedId); });
            if (customer) {
                setCustomerName(customer.firstName + ' ' + customer.lastName);
                setCustomerPhone(customer.phone || '');
            }
        } else {
            setCustomerName('');
            setCustomerPhone('');
        }

    }

    let days = 0;

    if (pickupDate && returnDate) {

        const pickup = new Date(pickupDate);
        const ret = new Date(returnDate);
        const diff = ret - pickup;
        days = Math.max(1, Math.ceil(diff / (1000 * 60 * 60 * 24)));

    }

    const total = days * (car.rentalPricePerDay || 0);

    function handleSubmit(e) {

        e.preventDefault();

        const rentalData = {
            carId: car.id,
            customerId: customerId ? parseInt(customerId) : null,
            customerName: customerName,
            customerPhone: customerPhone,
            pickupDate: pickupDate,
            returnDate: returnDate,
            rentalDays: days,
            totalCost: total
        };

        onSubmit(rentalData);

    }

    return (

        <div style={{ background: '#fff', borderRadius: '10px', padding: '0.8rem', boxShadow: '0 1px 4px rgba(0,0,0,0.06)', border: '2px solid #059669' }}>

            <div style={{ marginBottom: '0.5rem', paddingBottom: '0.4rem', borderBottom: '2px solid #059669' }}>

                <div style={{ fontWeight: 700, fontSize: '0.85rem', color: '#1a1a2e' }}>
                    Rent: {car.carName} ({car.plateNumber})
                </div>

            </div>

            <form onSubmit={handleSubmit}>

                <div style={{ marginBottom: '0.4rem' }}>

                    <label style={{ color: '#374151', fontSize: '0.7rem', fontWeight: 500, display: 'block', marginBottom: '0.15rem' }}>
                        Customer
                    </label>

                    <select value={customerId}
                        onChange={handleCustomerChange}
                        style={{ width: '100%', padding: '0.35rem 0.5rem', border: '1px solid #d1d5db', borderRadius: '4px', fontSize: '0.75rem', outline: 'none', background: '#fff', boxSizing: 'border-box' }}>

                        <option value="">-- Select customer --</option>
                        {customers.map(function(customer) {
                            return (
                                <option key={customer.id} value={customer.id}>
                                    {customer.firstName} {customer.lastName} ({customer.phone})
                                </option>
                            );
                        })}

                    </select>

                </div>

                <div style={{ marginBottom: '0.4rem' }}>

                    <label style={{ color: '#374151', fontSize: '0.7rem', fontWeight: 500, display: 'block', marginBottom: '0.15rem' }}>
                        Name
                    </label>

                    <input type="text"
                        value={customerName}
                        onChange={function(e) { setCustomerName(e.target.value); }}
                        required
                        placeholder="Juma Mohamed"
                        style={{ width: '100%', padding: '0.35rem 0.5rem', border: '1px solid #d1d5db', borderRadius: '4px', fontSize: '0.75rem', outline: 'none', boxSizing: 'border-box' }} />

                </div>

                <div style={{ marginBottom: '0.4rem' }}>

                    <label style={{ color: '#374151', fontSize: '0.7rem', fontWeight: 500, display: 'block', marginBottom: '0.15rem' }}>
                        Phone
                    </label>

                    <input type="text"
                        value={customerPhone}
                        onChange={function(e) { setCustomerPhone(e.target.value); }}
                        required
                        placeholder="+255-712-345-678"
                        style={{ width: '100%', padding: '0.35rem 0.5rem', border: '1px solid #d1d5db', borderRadius: '4px', fontSize: '0.75rem', outline: 'none', boxSizing: 'border-box' }} />

                </div>

                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.4rem', marginBottom: '0.4rem' }}>

                    <div>

                        <label style={{ color: '#374151', fontSize: '0.7rem', fontWeight: 500, display: 'block', marginBottom: '0.15rem' }}>
                            Pickup
                        </label>

                        <input type="date"
                            value={pickupDate}
                            onChange={function(e) { setPickupDate(e.target.value); }}
                            required
                            style={{ width: '100%', padding: '0.35rem 0.5rem', border: '1px solid #d1d5db', borderRadius: '4px', fontSize: '0.75rem', outline: 'none', boxSizing: 'border-box' }} />

                    </div>

                    <div>

                        <label style={{ color: '#374151', fontSize: '0.7rem', fontWeight: 500, display: 'block', marginBottom: '0.15rem' }}>
                            Return
                        </label>

                        <input type="date"
                            value={returnDate}
                            onChange={function(e) { setReturnDate(e.target.value); }}
                            required
                            style={{ width: '100%', padding: '0.35rem 0.5rem', border: '1px solid #d1d5db', borderRadius: '4px', fontSize: '0.75rem', outline: 'none', boxSizing: 'border-box' }} />

                    </div>

                </div>

                {days > 0 && (

                    <div style={{ background: '#fef3c7', border: '1px solid #fde68a', borderRadius: '6px', padding: '0.35rem 0.6rem', marginBottom: '0.4rem' }}>

                        <div style={{ display: 'flex', justifyContent: 'space-between', color: '#92400e', fontSize: '0.72rem' }}>

                            <span>
                                <strong>{days} day(s)</strong>
                            </span>

                            <span>
                                TSh {car.rentalPricePerDay?.toLocaleString()} x {days}
                            </span>

                        </div>

                        <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '0.15rem', paddingTop: '0.15rem', borderTop: '1px dashed #fde68a', fontSize: '0.82rem', fontWeight: 700, color: '#1a1a2e' }}>

                            <span>Total</span>
                            <span>TSh {total.toLocaleString()}</span>

                        </div>

                    </div>

                )}

                <div style={{ display: 'flex', gap: '0.4rem' }}>

                    <button type="submit"
                        disabled={days === 0}
                        style={{ flex: 1, padding: '0.4rem', background: days ? '#059669' : '#9ca3af', color: '#fff', border: 'none', borderRadius: '4px', fontWeight: 700, cursor: days ? 'pointer' : 'not-allowed', fontSize: '0.78rem' }}>
                        Confirm Rental
                    </button>

                    <button type="button" onClick={onCancel}
                        style={{ padding: '0.4rem 0.8rem', background: '#f3f4f6', color: '#374151', border: '1px solid #d1d5db', borderRadius: '4px', fontWeight: 500, cursor: 'pointer', fontSize: '0.78rem' }}>
                        Cancel
                    </button>

                </div>

            </form>

        </div>

    );

}

export default RentalForm;
